   zustellart_id                       VARCHAR(10)     COLLATE 'en-ci' NOT NULL COMMENT 'Kennzeichen fuer die Arten der Zustellung eines Belos Vorgangs (z. B. Kosten und Fracht, frei Haus verzollt)',
   belos_vorgangart_id                 VARCHAR(10)     COLLATE 'en-ci' NOT NULL COMMENT 'Kennzeichen für die Art des Belos Vorgangs (z. B. Beschaffung, Annahmeverweigerung)',
