   belos_adresse_absender_num_id       INTEGER    NOT NULL COMMENT 'numerischer Wert für die belos_adresse. Bei Märkten/Lägern ist hier die wup_id hinterlegt, ansonsten ein negativer Wert. Wird für Join-Zwecke benötigt',
   belos_adresse_abholung_id           VARCHAR(40)     COLLATE 'en-ci' NOT NULL COMMENT 'Eindeutiger Schlüssel zur Identifikation einer Belos Adresse',
   belos_adresse_empfaenger_id         VARCHAR(40)     COLLATE 'en-ci' NOT NULL COMMENT 'Eindeutiger Schlüssel zur Identifikation einer Belos Adresse',
   belos_adresse_spedition_id          VARCHAR(40)     COLLATE 'en-ci' NOT NULL COMMENT 'Eindeutiger Schlüssel zur Identifikation einer Belos Adresse',
