   lagernummer_id                      VARCHAR(4)      COLLATE 'en-ci' COMMENT 'ID der Lagernummer - höchste Ebene der Lagerhierarchie',
   system_id                           INTEGER    NOT NULL COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
   tour_id                             INTEGER    COMMENT 'Nummer des Transportes (Tour)',
   belosart_fg                         INTEGER    NOT NULL COMMENT 'Zeigt an, ob es sich bei dem Vorgang um einen Distributions- oder Beschaffungsvorgang handelt',
   leergut_abh_fg                      INTEGER    NOT NULL COMMENT 'Flag für Leergutabholung',
   retouren_fg                         INTEGER    NOT NULL COMMENT 'Retouren Flag',
