   anz_stellplatz                      NUMBER(29,2)     COMMENT 'Anzahl der Stellplätze aus SAP',
   anz_kolli                           NUMBER(29,2)     COMMENT 'Anzahl der Kollis',
   belos_sendungsstatus_id             INTEGER    DEFAULT 3 NOT NULL COMMENT 'referenziert auf die Lookup-Tabelle l_belos_tourstatus! Es werden nur die Ausprägungen 2 und 3 benutzt',
   rundlauf_transport_fg               INTEGER    NOT NULL COMMENT 'gesetzt bei Touren, die mehr als ein Ziel anfahren. Redundant zu tour, muss hier gespeichert werden, da belos_vorgang-Daten zeitlich vor tour-Daten geliefert werden.',
   fleischwerk_fg                      INTEGER    NOT NULL COMMENT 'zeigt an, ob innerhalb der Tour ein Fleischwerk beliefert wurde. Redundant zu tour, muss hier gespeichert werden, da belos_vorgang-Daten zeitlich vor tour-Daten geliefert werden.',
   distribution_abr_fg                 INTEGER    NOT NULL COMMENT 'zeigt einen abrechnungsrelevanten Vorgang an. Redundant zu tour, muss hier gespeichert werden, da belos_vorgang-Daten zeitlich vor tour-Daten geliefert werden.',
   brtgew_sendung                      NUMBER(29,3)    COMMENT 'Abrechnungsrelevantes Brutto-Gewicht der Sendung;',
   brtvol_stauraum                     NUMBER(29,3)    NOT NULL COMMENT 'Abrechnungsrelevantes Brutto-Volumen des erforderlichen Stauraums der Sendung',
   anz_stellplatz_belos                NUMBER(29,2)     COMMENT 'Anzahl der Stellplätze aus dem Belos-System',
   k_na_fg                             INTEGER    DEFAULT 0 NOT NULL COMMENT 'Flag steht für Kaufland-nur Abrechnung. Für Transportprozesse, die in Regie des Dienstleisters durchgeführt werden. Flag wird gesetzt, wenn das Referenzfeld der SST mit CU beginnt',
   belos_auftrag_id_extern             VARCHAR(40)     COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse: Auftragsnummer Warenlieferant aus der Quelle Referenz1 (Beginnt in der Quelle mit CU%)',
   belos_lieferschein_id               VARCHAR(40)     COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse Lieferscheinnummer aus deem Quellfeld Referenz2. ',
   belos_sendung_id_extern             VARCHAR(40)     COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse: Sendungsnummer Dienstleister aus dem Quellfeld Referenz4. Beginnt im Quellfeld mit SU%',
   belos_bestell_beleg_id_extern       VARCHAR(40)     COLLATE 'en-ci' COMMENT 'Nur für k_na-Prozesse: Bestellbelegnummerr aus dem Quellfeld Referenz3. Beginnt im Quellfeld mit PO%',
   referenz                            VARCHAR(255)    COLLATE 'en-ci' COMMENT 'Sonstige Eingaben Feld Referenznummer (enthält Referenz aus SST nde_sendung ohne PO (ab Oktober 2018 befüllt, davor null) - beschränkt auf 200 Zeichen)',
   mandant_id_debitor                  INTEGER    DEFAULT 1 NOT NULL COMMENT 'Mandant_ID zur Eindeutigkeit des Debitors (bisher nur DE =1 / 04.06.2016)',
   datzeit_sendung_offen               TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt "Sendung offen"',
   datzeit_ware_versandbereit          TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt "Ware versandbereit"',
   datzeit_sendung_beauftragt          TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt "Sendung beauftragt"',
   datzeit_system_zugestellt           TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt "Systemstatus zugestellt"',
   datzeit_abholung_bis                TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt "Abholtermin (bis)".',
   datzeit_zustellung_bis              TIMESTAMP_LTZ(9) COMMENT 'Zeitpunkt "Zustelltermin (bis)".',
   TD_UPDATE 	TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   TD_INSERT 	TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   CONSTRAINT PK_BELOS_VORGANG PRIMARY KEY (mandant_id, belos_vorgang_id) NOT ENFORCED
)  COMMENT = 'LIS - Der Belos Vorgang setzt sich aus dem Transportauftrag (mit den Logistikdaten) und den Sendungsinformationen (mit den Abrechnungsdaten) zusammen.';
